# Rasterfall map v2
# world minx maxx minz maxz room_limit
# 单一基地防守地图：玩家、三名原据点 AI 和 BASE 核心在中央区域守住尸潮。
# 刷怪区贴近世界四边，尸潮从远方边缘涌来。
world -33000 33000 -33000 33000 33000
# ground is the actual walkable surface; world above is only the maximum extent.
# This explicit base preserves the legacy arena until later map passes carve its
# west/north/east channels into separate ground regions.
ground -33000 33000 -33000 33000 272B31
start -13000 -12000 0 1024

# ── 单一基地防守区 ────────────────────────────────────────────────
floor -3000 3000 -3000 3000 294B45
label -1700 1700 -3300 -3100 80E0A0 BASE DEFENSE

# ── 起点安全屋（不变）───────────────────────────────────────────────
safe -1800 1800 -5700 -4000 start
button_wave_skip -1740 -4800 0
floor -1800 1800 -5700 -4000 245238
box -2000 -1800 -5700 -3800 1300 3F6751 visible collision
box 1800 2000 -5700 -3800 1300 3F6751 visible collision
box -1800 -600 -4000 -3800 1300 3F6751 visible collision
box 600 1800 -4000 -3800 1300 3F6751 visible collision
box -1800 -600 -5700 -5680 1300 3F6751 visible collision
box 600 1800 -5700 -5680 1300 3F6751 visible collision
model -1800 1800 -5700 -4000 1300 1500 3F6751 0
# 安全屋屋顶按模型顶面提供承载碰撞，范围外扩玩家半径。
platform -2180 2180 -5880 -3620 2400

# ── 开发者区（保留：测试按钮、武器桌、陈列台、贴图展示墙）──────────
# 空气墙与起点后墙同线；中心为开发者门。
# x=-20000 处为通往空气墙顶部的开发者快捷坡道，坡道进入墙体前达到
# 墙顶高度；坡尾略高于墙顶，使玩家碰撞圆接触墙侧前即可跨上顶部。
box -24000 -1800 -5900 -5700 3000 48C8E0 visible collision role=air_gate_left
ramp -21000 -19000 -15000 -5900 0 3979 z 477A66
label -21000 -19000 -14600 -14400 9FE8C8 DEV_RAMP_SLOPE_0.44
# 空气墙是完整的三维实体：顶面覆盖整段墙体，并向四周扩展一个玩家
# 碰撞半径。坡道侧的地面边界为 z=-6260，使整个碰撞圆在坡面完整
# 支撑结束处恰好切换到墙顶，避免提前抬升后被墙侧卡住。
platform -24180 -1620 -6260 -5520 3900
box 1800 24000 -5900 -5700 3000 48C8E0 visible collision role=air_gate_right
floor -24000 -1800 -5900 -5700 26394A
floor 1800 24000 -5900 -5700 26394A
label -23000 23000 -6200 -6000 70D8FF AIR WALL CONTROL LINE

